func TestImportGraphProperties(t *testing.T) {
	property := func(length uint8) bool {
		count := int(length%32) + 1
		files := map[string]string{}
		for n := 0; n < count; n++ {
			source := fmt.Sprintf("type T%d = Int\n", n)
			if n > 0 {
				source = fmt.Sprintf("import \"%d.refine\"\n", n-1) + source
			}
			files[fmt.Sprintf("%d.refine", n)] = source
		}
		entry := fmt.Sprintf("%d.refine", count-1)
		first, err := CompileSources(entry, files)
		if err != nil {
			return false
		}
		second, err := CompileSources(entry, first.Sources())
		return err == nil && len(first.Files()) == count && first.Program().Source() == second.Program().Source()
	}
	if err := quick.Check(property, &quick.Config{MaxCount: 1000}); err != nil {
		t.Fatal(err)
	}
}

